%% Split-pod plot of PHQ-9 distributions in training and test sets
% Required input:
%   DEP_train_test_split.mat generated by prepare_DEP_train_test_split.m
%
% The left half of each pod represents the training set; the right half
% represents the test set. Individual observations, mean diamonds, median
% lines, interquartile ranges, sample sizes, and standardized mean
% differences (SMDs) are shown.

clearvars;
clc;
close all;

%% -------------------------- Configuration -----------------------------
projectRoot = fileparts(mfilename('fullpath'));

splitFile = fullfile(projectRoot, 'DEP_train_test_split.mat');
masterFile = fullfile(projectRoot, 'v2', 'DEP-all', 'DEP-all.xlsx');

outputPng = fullfile(projectRoot, 'DEP_train_test_PHQ_podplot.png');
outputSvg = fullfile(projectRoot, 'DEP_train_test_PHQ_podplot.svg');
outputFig = fullfile(projectRoot, 'DEP_train_test_PHQ_podplot.fig');
outputXlsx = fullfile(projectRoot, 'DEP_train_test_PHQ_balance.xlsx');

groupFields = ["no_or_minimal", "mild", "moderate", "high"];
groupLabels = ["No/minimal", "Mild", "Moderate", "High"];

% Soft red/blue palette.
trainColor = [216, 144, 144] / 255;
testColor = [95, 137, 177] / 255;
trainEdge = [178, 34, 34] / 255;
testEdge = [16, 78, 139] / 255;

kernelBandwidth = 0.45;
maxPodWidth = 0.34;
pointJitterWidth = 0.25;
randomSeedForJitter = 20261014;

%% --------------------------- Load inputs ------------------------------
assert(isfile(splitFile), ...
    'Split MAT file does not exist:\n%s', splitFile);
loaded = load(splitFile, 'DEPsplit');
assert(isfield(loaded, 'DEPsplit'), ...
    'Variable DEPsplit was not found in:\n%s', splitFile);
DEPsplit = loaded.DEPsplit;

[masterIDs, phqScores, phqColumnName] = readMasterPHQ(masterFile);

assert(numel(unique(masterIDs)) == numel(masterIDs), ...
    'DEP-all.xlsx contains duplicate subject IDs.');

%% ---------------- Match PHQ-9 scores to split subjects ----------------
nGroup = numel(groupFields);
trainPHQ = cell(nGroup, 1);
testPHQ = cell(nGroup, 1);

nTrain = zeros(nGroup, 1);
nTest = zeros(nGroup, 1);
meanTrain = nan(nGroup, 1);
meanTest = nan(nGroup, 1);
sdTrain = nan(nGroup, 1);
sdTest = nan(nGroup, 1);
medianTrain = nan(nGroup, 1);
medianTest = nan(nGroup, 1);
iqrTrain = nan(nGroup, 1);
iqrTest = nan(nGroup, 1);
smd = nan(nGroup, 1);

for g = 1:nGroup
    groupName = char(groupFields(g));
    assert(isfield(DEPsplit.groups, groupName), ...
        'DEPsplit.groups.%s was not found.', groupName);

    trainIDs = DEPsplit.groups.(groupName).train.subject_ids;
    testIDs = DEPsplit.groups.(groupName).test.subject_ids;

    trainPHQ{g} = matchScores(trainIDs, masterIDs, phqScores, ...
        groupFields(g) + " training");
    testPHQ{g} = matchScores(testIDs, masterIDs, phqScores, ...
        groupFields(g) + " test");

    trainPHQ{g} = trainPHQ{g}(isfinite(trainPHQ{g}));
    testPHQ{g} = testPHQ{g}(isfinite(testPHQ{g}));

    nTrain(g) = numel(trainPHQ{g});
    nTest(g) = numel(testPHQ{g});
    assert(nTrain(g) >= 2 && nTest(g) >= 2, ...
        '%s does not contain enough finite PHQ-9 values.', groupFields(g));

    meanTrain(g) = mean(trainPHQ{g});
    meanTest(g) = mean(testPHQ{g});
    sdTrain(g) = std(trainPHQ{g}, 0);
    sdTest(g) = std(testPHQ{g}, 0);
    medianTrain(g) = median(trainPHQ{g});
    medianTest(g) = median(testPHQ{g});
    iqrTrain(g) = iqr(trainPHQ{g});
    iqrTest(g) = iqr(testPHQ{g});
    smd(g) = standardizedMeanDifference(trainPHQ{g}, testPHQ{g});
end

balanceTable = table(groupLabels(:), nTrain, nTest, ...
    meanTrain, meanTest, sdTrain, sdTest, medianTrain, medianTest, ...
    iqrTrain, iqrTest, smd, ...
    'VariableNames', {'group', 'n_train', 'n_test', ...
    'mean_train', 'mean_test', 'sd_train', 'sd_test', ...
    'median_train', 'median_test', 'IQR_train', 'IQR_test', 'SMD'});

%% --------------------------- Draw figure ------------------------------
rng(randomSeedForJitter, 'twister');

fig = figure('Color', 'w', 'Position', [100, 100, 1450, 820]);
ax = axes(fig);
hold(ax, 'on');

% PHQ-9 category boundaries.
for cutoff = [5, 10, 15]
    yline(ax, cutoff, '--', 'Color', [0.82, 0.82, 0.82], ...
        'LineWidth', 1.0, 'HandleVisibility', 'off');
end

allFiniteScores = vertcat(trainPHQ{:}, testPHQ{:});
yObservedMax = max(allFiniteScores);
annotationY = max(28.5, yObservedMax + 1.6);
yUpper = annotationY + 1.2;

for g = 1:nGroup
    xCenter = g;

    drawHalfPod(ax, xCenter, trainPHQ{g}, -1, trainColor, ...
        trainEdge, kernelBandwidth, maxPodWidth, pointJitterWidth);
    drawHalfPod(ax, xCenter, testPHQ{g}, +1, testColor, ...
        testEdge, kernelBandwidth, maxPodWidth, pointJitterWidth);

    % Mean labels are placed on the matching half of each pod.
    text(ax, xCenter - 0.23, meanTrain(g), ...
        sprintf('%.2f', meanTrain(g)), ...
        'HorizontalAlignment', 'right', ...
        'VerticalAlignment', 'middle', ...
        'Color', trainEdge, 'FontSize', 10, 'FontWeight', 'bold');
    text(ax, xCenter + 0.23, meanTest(g), ...
        sprintf('%.2f', meanTest(g)), ...
        'HorizontalAlignment', 'left', ...
        'VerticalAlignment', 'middle', ...
        'Color', testEdge, 'FontSize', 10, 'FontWeight', 'bold');

    % Counts and SMD are balance diagnostics, not significance tests.
    text(ax, xCenter, annotationY, ...
        sprintf('Train n=%d | Test n=%d\nSMD=%.3f', ...
        nTrain(g), nTest(g), smd(g)), ...
        'HorizontalAlignment', 'center', ...
        'VerticalAlignment', 'middle', ...
        'FontSize', 10.5, 'Color', [0.20, 0.20, 0.20]);
end

% Legend handles independent of the plotted patches.
hTrain = patch(ax, nan, nan, trainColor, ...
    'FaceAlpha', 0.65, 'EdgeColor', trainEdge, 'LineWidth', 1.0);
hTest = patch(ax, nan, nan, testColor, ...
    'FaceAlpha', 0.65, 'EdgeColor', testEdge, 'LineWidth', 1.0);
legend(ax, [hTrain, hTest], {'Training set', 'Test set'}, ...
    'Location', 'eastoutside', 'Box', 'off', 'FontSize', 11);

xlim(ax, [0.45, nGroup + 0.55]);
ylim(ax, [-0.75, yUpper]);
xticks(ax, 1:nGroup);
xticklabels(ax, groupLabels);
yticks(ax, 0:3:27);

xlabel(ax, 'PHQ-9 symptom group', 'FontSize', 13);
ylabel(ax, 'PHQ-9 score', 'FontSize', 13);
title(ax, 'PHQ-9 distributions in the training and test sets', ...
    'FontSize', 17, 'FontWeight', 'bold');

grid(ax, 'on');
ax.XGrid = 'off';
ax.GridAlpha = 0.16;
ax.LineWidth = 1.0;
ax.FontName = 'Arial';
ax.FontSize = 12;
ax.TickDir = 'out';
box(ax, 'off');

drawnow;

%% ---------------------------- Save outputs ----------------------------
exportgraphics(fig, outputPng, 'Resolution', 300);
exportgraphics(fig, outputSvg, 'ContentType', 'vector');
savefig(fig, outputFig);
writetable(balanceTable, outputXlsx, ...
    'Sheet', 'PHQ_balance', 'WriteMode', 'overwritesheet');

disp(balanceTable);
fprintf('\nPHQ-9 column used: %s\n', phqColumnName);
fprintf('Saved PNG: %s\n', outputPng);
fprintf('Saved SVG: %s\n', outputSvg);
fprintf('Saved FIG: %s\n', outputFig);
fprintf('Saved balance table: %s\n', outputXlsx);

%% --------------------------- Local functions --------------------------
function drawHalfPod(ax, xCenter, values, side, faceColor, edgeColor, ...
        bandwidth, maxWidth, jitterWidth)
    values = values(isfinite(values));

    yLow = max(0, min(values) - 0.75);
    yHigh = min(27, max(values) + 0.75);
    if yHigh <= yLow
        yLow = max(0, values(1) - 0.75);
        yHigh = min(27, values(1) + 0.75);
    end

    yGrid = linspace(yLow, yHigh, 220);
    density = ksdensity(values, yGrid, 'Bandwidth', bandwidth);
    density(~isfinite(density)) = 0;

    if max(density) > 0
        halfWidth = maxWidth * density / max(density);
    else
        halfWidth = zeros(size(density));
    end

    xCurve = xCenter + side * halfWidth;
    xBase = xCenter * ones(size(yGrid));
    patch(ax, [xBase, fliplr(xCurve)], [yGrid, fliplr(yGrid)], ...
        faceColor, 'FaceAlpha', 0.58, 'EdgeColor', edgeColor, ...
        'LineWidth', 1.0, 'HandleVisibility', 'off');

    % Points stay on their own half of the pod.
    pointOffset = 0.025 + jitterWidth * rand(size(values));
    xPoints = xCenter + side * pointOffset;
    scatter(ax, xPoints, values, 11, faceColor, 'filled', ...
        'MarkerFaceAlpha', 0.28, 'MarkerEdgeAlpha', 0.10, ...
        'HandleVisibility', 'off');

    quartiles = prctile(values, [25, 50, 75]);
    summaryX = xCenter + side * 0.075;
    line(ax, [summaryX, summaryX], quartiles([1, 3]), ...
        'Color', [0.15, 0.15, 0.15], 'LineWidth', 2.6, ...
        'HandleVisibility', 'off');
    line(ax, summaryX + [-0.045, 0.045], ...
        [quartiles(2), quartiles(2)], ...
        'Color', [0.05, 0.05, 0.05], 'LineWidth', 2.2, ...
        'HandleVisibility', 'off');
    scatter(ax, summaryX, mean(values), 45, edgeColor, 'd', 'filled', ...
        'MarkerEdgeColor', 'w', 'LineWidth', 0.8, ...
        'HandleVisibility', 'off');
end

function scores = matchScores(subjectIDs, masterIDs, masterScores, label)
    subjectIDs = lower(strip(string(subjectIDs)));
    [isMatched, masterIndex] = ismember(subjectIDs, masterIDs);
    assert(all(isMatched), ...
        '%s contains %d ID(s) not found in DEP-all.xlsx.', ...
        label, nnz(~isMatched));
    scores = masterScores(masterIndex);
end

function value = standardizedMeanDifference(x, y)
    x = x(isfinite(x));
    y = y(isfinite(y));
    nx = numel(x);
    ny = numel(y);
    pooledVariance = ((nx - 1) * var(x, 0) + ...
        (ny - 1) * var(y, 0)) / (nx + ny - 2);

    if pooledVariance > 0
        value = (mean(x) - mean(y)) / sqrt(pooledVariance);
    else
        value = NaN;
    end
end

function [idsNormalized, phqScores, phqColumnName] = readMasterPHQ(xlsxFile)
    assert(isfile(xlsxFile), 'Excel file does not exist:\n%s', xlsxFile);

    opts = detectImportOptions(xlsxFile, 'VariableNamingRule', 'preserve');
    T = readtable(xlsxFile, opts);
    assert(width(T) >= 2, ...
        'DEP-all.xlsx must contain an ID column and a PHQ-9 column.');

    names = string(T.Properties.VariableNames);
    normalizedNames = lower(regexprep(names, '[^a-zA-Z0-9]', ''));

    idCandidates = ["id", "subjectid", "participantid", ...
        "subject", "name"];
    phqCandidates = ["phqtotalscore", "phq9totalscore", ...
        "phq9", "phqtotal", "phqscore"];

    idColumn = find(ismember(normalizedNames, idCandidates), 1);
    if isempty(idColumn)
        idColumn = 1;
        warning('No named ID column found; using the first column.');
    end

    phqColumn = find(ismember(normalizedNames, phqCandidates), 1);
    if isempty(phqColumn)
        phqColumn = find(contains(normalizedNames, 'phq') & ...
            contains(normalizedNames, 'score'), 1);
    end
    assert(~isempty(phqColumn), ...
        ['Could not identify the PHQ-9 column in DEP-all.xlsx. ' ...
         'Available columns are: %s'], strjoin(names, ', '));

    rawIDs = strip(string(T{:, idColumn}));
    validID = ~ismissing(rawIDs) & rawIDs ~= "";
    rawIDs = rawIDs(validID);
    idsNormalized = lower(rawIDs);

    rawPHQ = T{validID, phqColumn};
    if isnumeric(rawPHQ) || islogical(rawPHQ)
        phqScores = double(rawPHQ);
    else
        phqScores = str2double(strip(string(rawPHQ)));
    end
    phqScores = phqScores(:);

    phqColumnName = names(phqColumn);
end
